export async function startRecording(devToolsPage: DevToolsPage): Promise<void> {
  await devToolsPage.click(CLEAR_BUTTON_SELECTOR);
  await devToolsPage.click(RECORD_BUTTON_SELECTOR);

  // Wait for the button to turn to its stop state.
  await devToolsPage.waitFor(STOP_BUTTON_SELECTOR);
  await expectVeEvents(devToolsPage,
                       [veClick('Toolbar > Toggle: timeline.toggle-recording'), veImpressionForStatusDialog()],
                       'Panel: timeline');
}

/**
 * Increases the timeout for the tests in the given context.
 * Useful for performance as tests that import or record a trace often get over the default timeout on slower bots.
 * Note that in e2e this can only be used on a `describe`, not an
 * `it`, hence why the type of the argument is `Mocha.Suite`
 */
export function increaseTimeoutForPerfPanel(context: Mocha.Suite): void {
  // If the timeout is 0, then we are in debug mode, and don't want to override
  // that.
  if (context.timeout()) {
    context.timeout(30_000);
  }
}
/**
 * @param checkHasActiveTrace Usually this only required for enhanced traces
 */
export async function loadTraceAndWaitToFullyRender(
    devToolsPage: DevToolsPage,
    initiateTraceLoadCb: () => Promise<unknown>,
    checkHasActiveTrace = false,
    ): Promise<number> {
  const panelElement = await devToolsPage.waitFor('.widget.panel.timeline');
  const [, traceLoadedData] = await Promise.all([
    initiateTraceLoadCb(),
    panelElement.evaluate(
        (el, checkPanelState) => {
          return new Promise<number>(async res => {
            // Set-up the event listener first to prevent further
            // race conditions.
            el.addEventListener('traceload', e => {
              const ev = e as Timeline.BenchmarkEvents.TraceLoadEvent;
              res(ev.duration);
            }, {once: true});
            if (checkPanelState) {
              // @ts-expect-error This is loaded inside the new DevTools page.
              const TimelineModule = await import('./panels/timeline/timeline.js');
              if (TimelineModule.TimelinePanel.TimelinePanel.instance().hasActiveTrace()) {
                res(-1);
              }
            }
          });
        },
        checkHasActiveTrace),
  ]);

  // There's a lot of scheduling/waiting in the Timeline panel's rendering stack
  // currently. Some events are fired, some things are debounced, some things wait
  // for the RenderCoordinator to update. So let's give all that plenty of time to
  // happen.
  await devToolsPage.timeout(200);
  await devToolsPage.raf();
  await devToolsPage.raf();

  return traceLoadedData;
}

export async function reloadAndRecord(devToolsPage: DevToolsPage): Promise<void> {
  await loadTraceAndWaitToFullyRender(devToolsPage, () => devToolsPage.click(RELOAD_AND_RECORD_BUTTON_SELECTOR));
  await expectVeEvents(devToolsPage,
                       [veClick('Toolbar > Action: timeline.record-reload'), veImpressionForStatusDialog()],
                       'Panel: timeline');
}

export async function stopRecording(devToolsPage: DevToolsPage): Promise<void> {
  await loadTraceAndWaitToFullyRender(devToolsPage, () => devToolsPage.click(STOP_BUTTON_SELECTOR));
  await expectVeEvents(devToolsPage,
                       [
                         veClick('Toolbar > Toggle: timeline.toggle-recording'),
                         veResize('Dialog: timeline-status'),
                       ],
                       'Panel: timeline');
}

export async function getTotalTimeFromSummary(devToolsPage: DevToolsPage): Promise<number> {
  const minCategories = 2;
  const categoryValues = await devToolsPage.waitForMany('.category-value', minCategories);

  const totalVal = categoryValues[categoryValues.length - 1];
  const totalText = await totalVal.evaluate(node => node.textContent as string);
  return parseInt(totalText, 10);
}

export async function getTotalTimeFromPie(devToolsPage: DevToolsPage): Promise<number> {
  const pieChartTotal = await devToolsPage.waitFor('.pie-chart-total');
  const totalText = await pieChartTotal.evaluate(node => node.textContent as string);
  return parseInt(totalText, 10);
}

export async function retrieveSelectedAndExpandedActivityItems(frontend: puppeteer.Page): Promise<string[]> {
  const treeItems = await frontend.$$('.expanded > td.activity-column,.selected > td.activity-column');
  const tree = [];
  for (const item of treeItems) {
    tree.push(await frontend.evaluate(el => el.innerText.split('\n')[0], item));
  }

  return tree;
}

